          "custom": "var myHeaders = new Headers();\nmyHeaders.append(\"TenantName\", \"snackbrands-au\");\nmyHeaders.append(\"Content-Type\", \"application/json\");\nmyHeaders.append(\"Authorization\", \"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..RLuaErkjwSYyxxjSOhB2UShUtkbYM3Hmb8wxtPmAx6c\");\n\ndocument.getElementById(\"statusResult\").innerHTML ='';\n\nvar raw = JSON.stringify(\n{\n    \"Query\":\n    {\n        \"CategoryNo\": 28,\n        \"Conditions\": [\n            {\n                \"Condition\": data.loginId,\n                \"FieldNoOrName\": \"412\"\n            },\n            {\n                \"Condition\": \"EMPTY\",\n                \"FieldNoOrName\": \"379\"\n            }\n        ],\n        \"SelectedFieldsNoOrNames\": [\n            \"Entry_ID\",\n            \"Staff_Login\"\n        ]\n    }\n}\n);\n\n\nvar requestOptions =\n{\n    method: 'POST',\n    headers: myHeaders,\n    body: raw,\n    redirect: 'follow'\n};\n\nfetch(\"https://snackbrands-au.thereforeonline.com/theservice/v0001/restun/ExecuteSingleQuery\", requestOptions)\n.then(response => response.text())\n.then(result =>\n{\n    let d = JSON.parse(result);\n    if (d && d.QueryResult && d.QueryResult.ResultRows.length > 0)\n    {\n    \n        let res = d.QueryResult.ResultRows[0];\n        data.entryId = res.IndexValues[0];\n        document.getElementById('entryId').value = res.IndexValues[0];\n        components.entryId.triggerChange();\n        components.entryId.triggerRedraw();\n        console.log(data);\n    }\n    else\n    {\n      document.getElementById('statusResult').innerHTML = \"You are not currently signed-in\";\n    }\n}\n)\n.catch(error => document.getElementById('statusResult').innerHTML = \"Error retrieving details.\");",
