        {
          "label": "Lookup...",
          "action": "custom",
          "state": "",
          "showValidations": false,
          "custom": "var myHeaders = new Headers();\r\nmyHeaders.append(\"TenantName\", \"snackbrands-au\");\r\nmyHeaders.append(\"Content-Type\", \"application/json\");\r\nmyHeaders.append(\"Authorization\", \"Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..RLuaErkjwSYyxxjSOhB2UShUtkbYM3Hmb8wxtPmAx6c\");\r\n\r\nlet phoneNumber = data.phoneNumber;\r\nif (!phoneNumber)\r\n{\r\n  alert(\"Please enter your phone number\");\r\n  return;\r\n}\r\ndata.entryId = '';\r\ndocument.getElementById(\"statusResult\").innerHTML ='';\r\n\r\n\r\n\r\nfunction GetLoginDetails()\r\n{\r\n\tlet raw = JSON.stringify(\r\n\t{\r\n\t\t\"Query\":\r\n\t\t{\r\n\t\t\t\"CategoryNo\": 28,\r\n\t\t\t\"Conditions\": [\r\n\t\t\t\t{\r\n\t\t\t\t\t\"Condition\": data.phoneNumber,\r\n\t\t\t\t\t\"FieldNoOrName\": \"382\"\r\n\t\t\t\t},\r\n\t\t\t\t{\r\n\t\t\t\t\t\"Condition\": \"EMPTY\",\r\n\t\t\t\t\t\"FieldNoOrName\": \"379\"\r\n\t\t\t\t}\r\n\t\t\t],\r\n\t\t\t\"SelectedFieldsNoOrNames\": [\r\n\t\t\t\t\"Entry_ID\", \"Location_TEXT\", \"Sub_Location\", \"Signin_Time\"\r\n\t\t\t]\r\n\t\t}\r\n\t}\r\n\t);\r\n\treturn raw;\r\n}\r\n\r\nvar requestOptions =\r\n{\r\n    method: 'POST',\r\n    headers: myHeaders,\r\n    body: GetLoginDetails(),\r\n    redirect: 'follow'\r\n};\r\n\r\n document.getElementById('overlay').style.display = \"block\";\r\n\r\nfetch(\"https://snackbrands-au.thereforeonline.com/theservice/v0001/restun/ExecuteSingleQuery\", requestOptions)\r\n.then(response => response.text())\r\n.then(result =>\r\n{\r\n    let d = JSON.parse(result);\r\n\tif (d)\r\n\t{\r\n\t\tswitch(d.QueryResult.ResultRows.length)\r\n\t\t{\r\n\t\t\tcase 0:\r\n\t\t\t\tsetStatus( \"You are not currently signed-in\", true);\r\n\t\t\t\tbreak;\r\n\t\t\tcase 1:\r\n\t\t\t\tdata.entryId = d.QueryResult.ResultRows[0].IndexValues[0];\r\n\t\t\t\tdocument.getElementById('entryId').value = d.QueryResult.ResultRows[0].IndexValues[0];\r\n\t\t\t\tlet location = d.QueryResult.ResultRows[0].IndexValues[1] + ' ' + d.QueryResult.ResultRows[0].IndexValues[2]\r\n\t\t\t\tlet loginTime = new Date(d.QueryResult.ResultRows[0].IndexValues[3]);\r\n\t\t\t\tcomponents.entryId.triggerChange();\r\n\t\t\t\tcomponents.entryId.triggerRedraw();\r\n\t\t\t\tsetStatus( \"Signed-in in at \" + location + \" (\" + loginTime.toLocaleString() +\"). <br>Please press Sign-Out button to sign out\", false);\r\n\t\t\t\tbreak;\r\n\t\t\tdefault:\r\n\t\t\t  let l = [];\r\n\t\t\t\td.QueryResult.ResultRows.forEach((v) => {\r\n\t\t\t\t\tl.push({\"entryIdGrid\": v.IndexValues[0], \"locationGrid\": v.IndexValues[1] + ' ' + v.IndexValues[2], \"signInTimeGrid\": new Date(v.IndexValues[3]).toLocaleString()})\r\n\t\t\t\t\t});\r\n\t\t\t\tdata.locations = l;\r\n\t\t\t\tcomponents.locations.triggerChange();\r\n\t\t\t\tcomponents.locations.triggerRedraw();\r\n\t\t\t\tsetStatus(\"You are signed-in at multiple locations.<br>Please Select the location to sign out of, then press Sign-Out\", false);\r\n\t\t}\r\n\t}\r\n})\r\n.catch(error =>{ console.log(error); setStatus(\"Error retrieving details.\", true)});\r\n\r\n\r\nfunction setStatus(message, isError)\r\n{\r\n   document.getElementById('overlay').style.display = \"none\";\r\n  let statusDiv = document.getElementById('statusResult');\r\n  statusDiv.innerHTML = message;\r\n  statusDiv.className = isError?\"bg-warning text-dark text-center\":\"bg-success text-light text-center\";\r\n}",
