IxProfile.InitScript:
var fileName = File.Title;
var regex = new RegExp( /(\d+) (.*)/gm );

var invoiceNo;
var supplierID;

var matches = regex.exec(fileName);
if (matches !== null)
{
	if (matches.length > 1)
	{
		supplierID = matches[1];
		invoiceNo = matches[2];
	}
	else
	{
		invoiceNo = matches[0];
	}
}

var owner = File.GetPath(0);

Profile.FilesToSave = File.Title + '.pdf';
var barcodes = Extractor.ExtractList("Barcode");

var loscomb = [];
var invno = [];
var palletno = [];


if (Array.isArray(barcodes))
{
	for(var i = 0; i < barcodes.length; i++)
	{
		var b = barcodes[i];
		var sb = b.split(',');
		if (Array.isArray(sb))
		{
			for (var ii = 0; ii < sb.length; ii++)
			{
				var v = sb[ii].replace(/\"/gm,'').trim();
				ProcessBarcodeValue(v);
			}
		}
		else
		{
			ProcessBarcdeValue(b.trim());
		}
	}
}


function ProcessBarcodeValue(bc)
{
	if (bc.substr(0,2) == 'LO') {loscomb.push(bc);}
	if (bc.substr(0,3) == 'SIN') {invno.push(bc);}
	if (bc.substr(0,3) == 'LXS'){palletno.push(bc);}
}
